    q("Second Conditional: If there ___ no trees on Earth, humans could not survive.", "were", "are", "will be", "had been", "Unreal present plural condition uses 'were'."),
    q("Third Conditional: If the doctor had arrived earlier, the patient ___ survived.", "would have", "would", "will have", "had", "Type 3: 'If + had + V3, subject + would have + V3'."),
    q("Third Conditional: If you ___ harder last term, you would have won the prize.", "had studied", "studied", "study", "would study", "Type 3 'If' clause requires Past Perfect 'had studied'."),
    q("Third Conditional: They would have caught the train if they ___ left home earlier.", "had", "have", "were", "would", "Type 3 uses 'had + V3 (left)' in the 'If' clause."),
