    q("Second Conditional: If she ___ the truth, she wouldn't stay silent.", "knew", "knows", "will know", "had known", "Unreal present knowledge uses Simple Past 'knew'."),
    q("Second Conditional: We ___ buy a larger bus if the school had the funds.", "could", "can", "will", "had", "Type 2 past condition 'had' pairs with 'could'."),
    q("Second Conditional: If people ___ fewer plastic bags, beaches would stay clean.", "used", "use", "will use", "had used", "Hypothetical Type 2 takes Simple Past 'used'."),
    q("Second Conditional: He wouldn't cough so much if he ___ in clean air.", "lived", "lives", "will live", "had lived", "Main clause 'wouldn't cough' pairs with Simple Past 'lived'."),
    q("Third Conditional: If you had warned me, I ___ fallen into that ditch.", "wouldn't have", "won't have", "didn't", "wouldn't", "Past counterfactual pairs 'had warned' with 'wouldn't have fallen'."),
    q("Third Conditional: If the driver had braked sooner, the crash ___ happened.", "wouldn't have", "won't", "didn't", "hadn't", "Unfulfilled past avoidance takes 'wouldn't have happened'."),
    q("Third Conditional: They ___ reached Galle by noon if the bus hadn't broken down.", "would have", "will have", "would", "had", "Type 3 main clause takes 'would have + V3 (reached)'."),
    q("Third Conditional: If I ___ brought my camera, I could have photographed the deer.", "had", "have", "was", "would", "Type 3 condition requires 'had + V3 (brought)'."),
    q("Third Conditional: She would have scored 95 if she ___ checked her answers.", "had", "has", "did", "would", "Type 3 requires 'had checked'."),
